        ...E(1, {consigne: "Puis `if (c > max) max = c;` avec `c = [[C]]`. Que vaut `max` à la fin ?", "verif.attendu": "[[MAX]]", corrige: "[[C]] > [[M1]] ? [[R2]] → `max` vaut **[[MAX]]**.", indices: ["Compare [[C]] à la valeur actuelle de `max` ([[M1]]).", "[[MAX]]"]}),
        ...E(2, {consigne: "Même méthode pour le minimum : `min = a`, puis `if (b < min) min = b;`, puis `if (c < min) min = c;`. Que vaut `min` ?", "verif.attendu": "[[MIN]]", corrige: "Le plus petit de [[A]], [[B]], [[C]] : **[[MIN]]**.", indices: ["Même raisonnement avec `<`.", "[[MIN]]"]}),
