        ...E(1, {consigne: "Applique la règle à [[Y1]] : est-elle bissextile ? (1 pour oui, 0 pour non)", "verif.attendu": "[[R1]]", corrige: "[[EXP1]]", indices: ["Teste d'abord : multiple de 400 ? de 100 ? de 4 ?", "[[R1]]"]}),
